      }
    }
  ],
  "dataModel": {
    "value": {
      "rainTaxi": {
        "title": "雨天打车",
        "hint": "勾选即导航",
        "icon": "assets/rainy-umbrella.png",
        "destinations": [
          {
            "name": "公司",
            "address": "深圳湾科技园",
            "selected": false
          },
          {
            "name": "家",
            "address": "南山家里",
            "selected": false
          },
          {
            "name": "客户",
            "address": "福田客户处",
            "selected": false
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "umbrella_icon",
      "src": "assets/rainy-umbrella.png",
      "use": "rainy taxi umbrella icon",
      "description": "雨伞图标素材，用于表达下雨天打车场景的中心视觉，适合在小尺寸卡片中作为清爽主图标。",
      "bindTo": "/rainTaxi/icon",
      "static": true
    }
  ]
}

